import{_ as e,o as a,c as s,a2 as n}from"./chunks/framework.BEmfQga0.js";const h=JSON.parse('{"title":"Plugin Directory Structure","description":"","frontmatter":{},"headers":[],"relativePath":"plugin-development/directory-structure.md","filePath":"plugin-development/directory-structure.md","lastUpdated":1788258471000}'),r={name:"plugin-development/directory-structure.md"};function o(l,t,i,d,c,p){return a(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="plugin-directory-structure" tabindex="-1">Plugin Directory Structure <a class="header-anchor" href="#plugin-directory-structure" aria-label="Permalink to &quot;Plugin Directory Structure&quot;">​</a></h1><p>The TokenPilot reference component is composed from shared LightRSI packages, a preset, products, and host adapters.</p><h2 id="top-level-layout" tabindex="-1">Top-Level Layout <a class="header-anchor" href="#top-level-layout" aria-label="Permalink to &quot;Top-Level Layout&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>components/</span></span>
<span class="line"><span>├── adapters/</span></span>
<span class="line"><span>│   ├── openclaw/         # OpenClaw adapter, hooks, commands, embedded proxy</span></span>
<span class="line"><span>│   ├── codex/            # Codex CLI adapter, hooks, provider install, local proxy</span></span>
<span class="line"><span>│   ├── claude-code/      # Claude Code adapter, gateway routing, MCP recovery</span></span>
<span class="line"><span>│   └── deepseek-harness/ # DeepSeek Harness Cordis adapter</span></span>
<span class="line"><span>├── products/</span></span>
<span class="line"><span>│   ├── cli/              # Shared lightrsi CLI surface</span></span>
<span class="line"><span>│   └── mcp/              # Shared memory_fault_recover MCP server</span></span>
<span class="line"><span>├── presets/</span></span>
<span class="line"><span>│   └── tokenpilot/       # TokenPilot feature composition</span></span>
<span class="line"><span>└── packages/</span></span>
<span class="line"><span>    ├── foundation/      # Contracts, history, runtime, and host-neutral primitives</span></span>
<span class="line"><span>    └── features/        # Stabilizer, reduction, eviction, cleaner, and memory</span></span></code></pre></div><h2 id="directory-purpose" tabindex="-1">Directory Purpose <a class="header-anchor" href="#directory-purpose" aria-label="Permalink to &quot;Directory Purpose&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Directory</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>packages/foundation/kernel/</code></td><td style="text-align:left;">Shared contracts, events, and runtime-facing types</td></tr><tr><td style="text-align:left;"><code>packages/foundation/runtime-core/</code></td><td style="text-align:left;">Host-agnostic runtime engine and reduction pipeline</td></tr><tr><td style="text-align:left;"><code>packages/foundation/history/</code></td><td style="text-align:left;">Canonical state, anchors, and lifecycle bookkeeping</td></tr><tr><td style="text-align:left;"><code>packages/foundation/host-adapter/</code></td><td style="text-align:left;">Shared host contracts and path-resolution interfaces</td></tr><tr><td style="text-align:left;"><code>packages/foundation/product-surface/</code></td><td style="text-align:left;">Shared user-facing command actions and product semantics</td></tr><tr><td style="text-align:left;"><code>packages/features/eviction/</code></td><td style="text-align:left;">Reduction and eviction analysis / policy logic</td></tr><tr><td style="text-align:left;"><code>packages/features/memory/</code></td><td style="text-align:left;">Experimental memory layer still under active development</td></tr><tr><td style="text-align:left;"><code>presets/tokenpilot/</code></td><td style="text-align:left;">TokenPilot composition and presentation identity</td></tr></tbody></table><h3 id="adapters-—-host-specific-integration" tabindex="-1"><code>adapters/</code> — Host-Specific Integration <a class="header-anchor" href="#adapters-—-host-specific-integration" aria-label="Permalink to &quot;\`adapters/\` — Host-Specific Integration&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Directory</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>adapters/&lt;host&gt;/</code></td><td style="text-align:left;">Host install/uninstall flow, config mutation, request/response hooks, session/transcript bridging, host-specific commands, runtime bootstrap, and doctor checks</td></tr></tbody></table><h3 id="products-—-shared-entrypoints" tabindex="-1"><code>products/</code> — Shared Entrypoints <a class="header-anchor" href="#products-—-shared-entrypoints" aria-label="Permalink to &quot;\`products/\` — Shared Entrypoints&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Directory</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>products/cli/</code></td><td style="text-align:left;">Standalone CLI surface for hosts without native slash commands</td></tr><tr><td style="text-align:left;"><code>products/mcp/</code></td><td style="text-align:left;">Shared MCP server surface, including <code>memory_fault_recover</code></td></tr></tbody></table><p>The adapter internal structure is described in <a href="https://github.com/zjunlp/LightRSI/blob/main/components/adapters/README.md" target="_blank" rel="noreferrer">adapters/README.md</a>.</p><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="/LightRSI/plugin-development/runtime-api">Runtime API</a> — the shared packages and their public surfaces</li></ul>`,13)])])}const g=e(r,[["render",o]]);export{h as __pageData,g as default};
